import {
  AuthOrchestrationOperateScope,
  AuthOrchestrationReadScope,
  AuthRelayReadScope,
  AuthRelayWriteScope,
  WS_METHODS,
  WsRpcGroup,
} from "@t3tools/contracts";
import { describe, expect, it } from "@effect/vitest";

import { RPC_REQUIRED_SCOPES, requiredScopeForRpcMethod } from "./RpcAuthorization.ts";

describe("RPC authorization scopes", () => {
  it("requires orchestration read access for attention synchronization", () => {
    expect(requiredScopeForRpcMethod(WS_METHODS.attentionSubscribe)).toBe(AuthOrchestrationReadScope);
  });
  it("declares exactly one scope for every RPC in the server group", () => {
    expect(new Set(Object.keys(RPC_REQUIRED_SCOPES))).toEqual(new Set(WsRpcGroup.requests.keys()));
  });

  it("authorizes background policy reporting and observation deliberately", () => {
    expect(requiredScopeForRpcMethod(WS_METHODS.serverReportClientActivity)).toBe(
      AuthOrchestrationReadScope,
    );
    expect(requiredScopeForRpcMethod(WS_METHODS.serverReportHostPowerState)).toBe(
      AuthOrchestrationOperateScope,
    );
    expect(requiredScopeForRpcMethod(WS_METHODS.serverGetBackgroundPolicy)).toBe(
      AuthOrchestrationReadScope,
    );
    expect(requiredScopeForRpcMethod(WS_METHODS.subscribeBackgroundPolicy)).toBe(
      AuthOrchestrationReadScope,
    );
  });

  it("allows relay status reads without granting relay installation access", () => {
    expect(requiredScopeForRpcMethod(WS_METHODS.cloudGetRelayClientStatus)).toBe(
      AuthRelayReadScope,
    );
    expect(requiredScopeForRpcMethod(WS_METHODS.cloudInstallRelayClient)).toBe(AuthRelayWriteScope);
  });

  it("requires permission to operate on a thread before uploading feedback", () => {
    expect(requiredScopeForRpcMethod(WS_METHODS.providerUploadFeedback)).toBe(
      AuthOrchestrationOperateScope,
    );
  });

  it("requires write access to import agent session history", () => {
    expect(requiredScopeForRpcMethod(WS_METHODS.agentSessionsScan)).toBe(
      AuthOrchestrationReadScope,
    );
    expect(requiredScopeForRpcMethod(WS_METHODS.agentSessionsImport)).toBe(
      AuthOrchestrationOperateScope,
    );
  });

  it("reads the reviewer menu under the same scope as the pull request it belongs to", () => {
    // The candidate list is a read like the detail beside it, and asking somebody for a review is
    // a write like every other pull request operation.
    expect(requiredScopeForRpcMethod(WS_METHODS.pullRequestsReviewerCandidates)).toBe(
      requiredScopeForRpcMethod(WS_METHODS.pullRequestsDetail),
    );
    expect(requiredScopeForRpcMethod(WS_METHODS.pullRequestsRequestReviewers)).toBe(
      requiredScopeForRpcMethod(WS_METHODS.pullRequestsComment),
    );
  });

  it("rejects unknown RPC method names", () => {
    for (const method of ["server.notRegistered", "toString", "constructor"]) {
      expect(() => requiredScopeForRpcMethod(method)).toThrow(
        `RPC method ${method} has no declared authorization scope.`,
      );
    }
  });
});

import {
  EnvironmentId,
  PROVIDER_SEND_TURN_MAX_FILE_BYTES,
  type ExecutionEnvironmentDescriptor,
} from "@t3tools/contracts";
import { HostProcessArchitecture, HostProcessPlatform } from "@t3tools/shared/hostProcess";
import * as Context from "effect/Context";
import * as Crypto from "effect/Crypto";
import * as Effect from "effect/Effect";
import * as FileSystem from "effect/FileSystem";
import * as Layer from "effect/Layer";
import * as Path from "effect/Path";
import * as Schema from "effect/Schema";

import packageJson from "../../package.json" with { type: "json" };
import * as ServerSecretStore from "../auth/ServerSecretStore.ts";
import { readAgentActivityPublishingActive } from "../cloud/config.ts";
import { resolveServerSelfUpdateCapability } from "../cloud/selfUpdate.ts";
import { resolveServiceLauncherMode } from "../cloud/serviceLauncherClient.ts";
import * as ServerConfig from "../config.ts";
import * as ProcessRunner from "../processRunner.ts";
import { resolveServerEnvironmentLabel } from "./ServerEnvironmentLabel.ts";
import { detectServerEnvironmentMachineKind } from "./ServerEnvironmentMachine.ts";

export class ServerEnvironmentIdPersistenceError extends Schema.TaggedError<ServerEnvironmentIdPersistenceError>()(
  "ServerEnvironmentIdPersistenceError",
  {
    operation: Schema.Literals(["check", "read", "write", "initialize"]),
    environmentIdPath: Schema.String,
    cause: Schema.optional(Schema.Defect()),
  },
) {
  override get message(): string {
    if (this.operation === "initialize") {
      return `Server environment ID file is missing or empty after initialization at '${this.environmentIdPath}'.`;
    }
    return `Server environment ID ${this.operation} failed at '${this.environmentIdPath}'.`;
  }
}

export class ServerEnvironment extends Context.Service<
  ServerEnvironment,
  {
    readonly getEnvironmentId: Effect.Effect<EnvironmentId>;
    readonly getDescriptor: Effect.Effect<ExecutionEnvironmentDescriptor>;
  }
>()("t3/environment/ServerEnvironment") {}

export class ServerEnvironmentIdentity extends Context.Service<
  ServerEnvironmentIdentity,
  {
    readonly getEnvironmentId: Effect.Effect<EnvironmentId>;
  }
>()("t3/environment/ServerEnvironment/ServerEnvironmentIdentity") {}

function platformOs(platform: NodeJS.Platform): ExecutionEnvironmentDescriptor["platform"]["os"] {
  switch (platform) {
    case "darwin":
      return "darwin";
    case "linux":
      return "linux";
    case "win32":
      return "windows";
    default:
      return "unknown";
  }
}

function platformArch(
  architecture: NodeJS.Architecture,
): ExecutionEnvironmentDescriptor["platform"]["arch"] {
  switch (architecture) {
    case "arm64":
      return "arm64";
    case "x64":
      return "x64";
    default:
      return "other";
  }
}

const makeIdentity = Effect.gen(function* () {
  const fileSystem = yield* FileSystem.FileSystem;
  const serverConfig = yield* ServerConfig.ServerConfig;
  const crypto = yield* Crypto.Crypto;

  const readPersistedEnvironmentId = Effect.gen(function* () {
    const exists = yield* fileSystem.exists(serverConfig.environmentIdPath).pipe(
      Effect.mapError(
        (cause) =>
          new ServerEnvironmentIdPersistenceError({
            operation: "check",
            environmentIdPath: serverConfig.environmentIdPath,
            cause,
          }),
      ),
    );
    if (!exists) {
      return null;
    }

    const raw = yield* fileSystem.readFileString(serverConfig.environmentIdPath).pipe(
      Effect.map((value) => value.trim()),
      Effect.mapError(
        (cause) =>
          new ServerEnvironmentIdPersistenceError({
            operation: "read",
            environmentIdPath: serverConfig.environmentIdPath,
            cause,
          }),
      ),
    );

    return raw.length > 0 ? raw : null;
  });

  const persistEnvironmentId = Effect.fn("ServerEnvironmentIdentity.persistEnvironmentId")(
    function* (value: string, mode: "create" | "recover") {
      const destinationPath =
        mode === "recover"
          ? `${serverConfig.environmentIdPath}.recovery`
          : serverConfig.environmentIdPath;
      const tempPath = yield* fileSystem.makeTempFileScoped({
        directory: serverConfig.stateDir,
        prefix: ".environment-id-",
      });
      yield* fileSystem.writeFileString(tempPath, `${value}\n`);
      // Publish the completed file without replacing an ID created by another process.
      yield* fileSystem
        .link(tempPath, destinationPath)
        .pipe(
          Effect.catch((cause) =>
            cause.reason._tag === "AlreadyExists" ? Effect.void : Effect.fail(cause),
          ),
        );
      if (mode === "recover") {
        // Keep the recovery ID so delayed initializers also publish the same winner.
        yield* fileSystem.remove(tempPath);
        yield* fileSystem.copyFile(destinationPath, tempPath);
        yield* fileSystem.rename(tempPath, serverConfig.environmentIdPath);
      }
    },
    Effect.scoped,
    Effect.mapError(
      (cause) =>
        new ServerEnvironmentIdPersistenceError({
          operation: "write",
          environmentIdPath: serverConfig.environmentIdPath,
          cause,
        }),
    ),
  );

  const environmentIdRaw = yield* Effect.gen(function* () {
    const persisted = yield* readPersistedEnvironmentId;
    if (persisted) {
      return persisted;
    }

    const generated = yield* crypto.randomUUIDv4;
    yield* persistEnvironmentId(generated, "create");
    let winner = yield* readPersistedEnvironmentId;
    if (winner === null) {
      yield* persistEnvironmentId(generated, "recover");
      winner = yield* readPersistedEnvironmentId;
    }
    if (winner === null) {
      return yield* new ServerEnvironmentIdPersistenceError({
        operation: "initialize",
        environmentIdPath: serverConfig.environmentIdPath,
      });
    }
    return winner;
  });

  const environmentId = EnvironmentId.make(environmentIdRaw);
  return ServerEnvironmentIdentity.of({
    getEnvironmentId: Effect.succeed(environmentId),
  });
});

/** @public Service construction is part of the canonical Effect module API. */
export const make = Effect.gen(function* () {
  const path = yield* Path.Path;
  const serverConfig = yield* ServerConfig.ServerConfig;
  const secrets = yield* ServerSecretStore.ServerSecretStore;
  const identity = yield* ServerEnvironmentIdentity;
  const hostPlatform = yield* HostProcessPlatform;
  const hostArchitecture = yield* HostProcessArchitecture;
  const environmentId = yield* identity.getEnvironmentId;
  const cwdBaseName = path.basename(serverConfig.cwd).trim();
  const label = yield* resolveServerEnvironmentLabel({ cwdBaseName });
  const machine = yield* detectServerEnvironmentMachineKind();
  const launcher = yield* resolveServiceLauncherMode();
  const serverSelfUpdate = resolveServerSelfUpdateCapability({
    desktopManaged: serverConfig.mode === "desktop",
    launcherManaged: launcher.managed,
  });
  // Static is correct: the control fd is known at bootstrap, and the desktop
  // app and its bundled server ship in one artifact, so a present fd means
  // the app speaks the requestDesktopUpdate protocol. WSL backends never get
  // the fd and correctly do not advertise.
  const desktopAppUpdate =
    serverSelfUpdate === "desktop-managed" && serverConfig.desktopTelemetryControlFd !== undefined;

  const descriptor: ExecutionEnvironmentDescriptor = {
    environmentId,
    label,
    platform: {
      os: platformOs(hostPlatform),
      arch: platformArch(hostArchitecture),
      ...(machine === null ? {} : { machine }),
    },
    serverVersion: packageJson.version,
    capabilities: {
      attentionSync: true,
      repositoryIdentity: true,
      connectionProbe: true,
      attachmentUploads: true,
      questionAttachments: true,
      fileAttachments: { maxUploadBytes: PROVIDER_SEND_TURN_MAX_FILE_BYTES },
      pullRequests: true,
      inlineMessageContext: true,
      threadSettlement: true,
      threadAutoSettlement: true,
      threadRestartContinuation: true,
      projectSettingsOverrides: true,
      threadSnooze: true,
      environmentThemes: true,
      usageLimitSources: true,
      usagePriceOverrides: true,
      threadPinning: true,
      threadPinReorder: true,
      threadActiveReorder: true,
      threadTitleRegeneration: true,
      threadPullRequests: true,
      pullRequestStackActions: true,
      threadPullRequestLinking: true,
      environmentIcon: true,
      projectCloneTracking: true,
      ...(serverSelfUpdate === null ? {} : { serverSelfUpdate }),
      ...(serverSelfUpdate === "boot-service" || desktopAppUpdate
        ? {
            serverSelfUpdateProgress: true,
            serverUpdateThreadContinuation: true,
          }
        : {}),
      ...(desktopAppUpdate ? { desktopAppUpdate: true } : {}),
    },
  };

  return ServerEnvironment.of({
    getEnvironmentId: Effect.succeed(environmentId),
    // The publish opt-in and relay link change at runtime (`t3 connect
    // publish`, the client settings toggle), so the capability is read per
    // descriptor request rather than baked in at startup.
    getDescriptor: readAgentActivityPublishingActive(secrets).pipe(
      Effect.map((agentActivityPublishing) => ({
        ...descriptor,
        capabilities: { ...descriptor.capabilities, agentActivityPublishing },
      })),
    ),
  });
});

export const identityLayer = Layer.effect(ServerEnvironmentIdentity, makeIdentity);

/**
 * ServerEnvironment is acquired from persisted filesystem and host-process
 * state. It intentionally has no fallback Layer.succeed value: callers must
 * provide the external platform services, a ServerConfig, and the
 * ServerSecretStore backing the descriptor's publishing capability.
 */
export const layer = Layer.effect(ServerEnvironment, make).pipe(
  Layer.provideMerge(identityLayer),
  Layer.provide(ProcessRunner.layer),
);

import {
  CommandId,
  EventId,
  EnvironmentId,
  ProjectId,
  ProviderInstanceId,
  ThreadId,
  TurnId,
  EnvironmentAuthorizationError,
  AuthOrchestrationReadScope,
  type AttentionSubscribeInput,
  type AttentionStreamMessage,
  AttentionEntity,
  AttentionDeliveryCursor,
} from "@t3tools/contracts";
import {
  emptyAttentionSync,
  reduceAttentionStream,
  attentionSyncFailed,
} from "@t3tools/client-runtime/attention-sync";
import * as HashMap from "effect/HashMap";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as Stream from "effect/Stream";
import * as SqlClient from "effect/unstable/sql/SqlClient";
import * as TestClock from "effect/testing/TestClock";
import * as PubSub from "effect/PubSub";
import * as Fiber from "effect/Fiber";
import * as Deferred from "effect/Deferred";
import * as Schema from "effect/Schema";
import * as FileSystem from "effect/FileSystem";
import * as Path from "effect/Path";
import * as NodeServices from "@effect/platform-node/NodeServices";
import { assert, describe, it } from "@effect/vitest";
import {
  SqlitePersistenceMemory,
  makeSqlitePersistenceLive,
} from "../persistence/Layers/Sqlite.ts";
import * as RepositoryIdentityResolver from "../project/RepositoryIdentityResolver.ts";
import { OrchestrationLayerLive } from "./runtimeLayer.ts";
import { ServerConfig } from "../config.ts";
import { OrchestrationEngineService } from "./Services/OrchestrationEngine.ts";
import { ProjectionThreadAttentionCurrentRepository } from "../persistence/Services/ProjectionThreadAttentionCurrent.ts";
import { OrchestrationProjectionPipeline } from "./Services/ProjectionPipeline.ts";
import { makeAttentionStream, ATTENTION_BOOTSTRAP_MS } from "./AttentionSync.ts";
const decodeEntity = Schema.decodeUnknownEffect(Schema.fromJsonString(AttentionEntity));

const layer = (dbPath?: string) =>
  OrchestrationLayerLive.pipe(
    Layer.provideMerge(RepositoryIdentityResolver.layer),
    Layer.provideMerge(dbPath ? makeSqlitePersistenceLive(dbPath) : SqlitePersistenceMemory),
    Layer.provideMerge(ServerConfig.layerTest(process.cwd(), { prefix: "t3-attention-sync-" })),
    Layer.provideMerge(NodeServices.layer),
  );
const setup = Effect.gen(function* () {
  const engine = yield* OrchestrationEngineService;
  const sql = yield* SqlClient.SqlClient;
  const attention = yield* ProjectionThreadAttentionCurrentRepository;
  const pipeline = yield* OrchestrationProjectionPipeline;
  let id = 0;
  let allowed = true;
  const authorization = yield* PubSub.unbounded<void>();
  const options = {
    environmentId: EnvironmentId.make("env"),
    scopeBinding: "session:orchestration:read",
    secret: new Uint8Array(32).fill(7),
    authorize: Effect.suspend(() =>
      allowed
        ? Effect.void
        : Effect.fail(
            new EnvironmentAuthorizationError({
              requiredScope: AuthOrchestrationReadScope,
              message: "Session revoked.",
            }),
          ),
    ),
    authorizationChanges: Stream.fromPubSub(authorization),
  };
  const now = "2026-09-28T00:00:00.000Z";
  const command = () => CommandId.make(`sync-command-${++id}`);
  const project = ProjectId.make("project");
  yield* engine.dispatch({
    type: "project.create",
    commandId: command(),
    projectId: project,
    title: "Project",
    workspaceRoot: "/tmp/attention-fixture",
    defaultModelSelection: null,
    createdAt: now,
  });
  const thread = (name: string) =>
    engine.dispatch({
      type: "thread.create",
      commandId: command(),
      threadId: ThreadId.make(name),
      projectId: project,
      title: name,
      modelSelection: { instanceId: ProviderInstanceId.make("codex"), model: "gpt-5-mini" },
      runtimeMode: "approval-required",
      interactionMode: "default",
      branch: null,
      worktreePath: null,
      createdAt: now,
    });
  const activity = (threadId: string, kind: string, requestId: string) =>
    engine.dispatch({
      type: "thread.activity.append",
      commandId: command(),
      threadId: ThreadId.make(threadId),
      createdAt: now,
      activity: {
        id: EventId.make(`sync-activity-${id}`),
        kind,
        turnId: TurnId.make("turn"),
        tone: "info",
        summary: "private",
        payload: { requestId, detail: "private command" },
        createdAt: now,
      },
    });
  const connect = Effect.fn("test.connectAttention")(function* (
    input: AttentionSubscribeInput = {},
  ) {
    const pull = yield* Stream.toPull(makeAttentionStream(input, options));
    const next = () =>
      pull.pipe(
        Effect.map((frames) => {
          assert.lengthOf(frames, 1);
          return frames[0]!;
        }),
      );
    return { next };
  });
  const revoke = Effect.gen(function* () {
    allowed = false;
    yield* PubSub.publish(authorization, undefined);
  });
  return {
    engine,
    sql,
    attention,
    pipeline,
    options,
    thread,
    activity,
    command,
    connect,
    revoke,
    now,
  };
});

describe("attention snapshot/live continuity", () => {
  it.effect("rotates delivery generation across a real disk-backed server restart", () =>
    Effect.gen(function* () {
      const fs = yield* FileSystem.FileSystem;
      const path = yield* Path.Path;
      const directory = yield* fs.makeTempDirectoryScoped({
        prefix: "t3-attention-delivery-restart-",
      });
      const db = path.join(directory, "state.sqlite");
      const cursor = yield* Effect.gen(function* () {
        const f = yield* setup;
        yield* f.thread("thread");
        const stream = yield* f.connect();
        let cache = emptyAttentionSync();
        while (cache.status !== "live") cache = reduceAttentionStream(cache, yield* stream.next());
        return cache.cursor!;
      }).pipe(Effect.scoped, Effect.provide(Layer.fresh(layer(db))));
      yield* Effect.gen(function* () {
        const f = yield* setup;
        const stream = yield* f.connect({ cursor });
        assert.deepEqual(yield* stream.next(), {
          type: "reset-required",
          reason: "generation-changed",
        });
        const fresh = yield* f.connect();
        let cache = emptyAttentionSync();
        while (cache.status !== "live") cache = reduceAttentionStream(cache, yield* fresh.next());
        assert.equal(HashMap.size(cache.entries), 1);
      }).pipe(Effect.scoped, Effect.provide(Layer.fresh(layer(db))));
    }).pipe(Effect.scoped, Effect.provide(NodeServices.layer)),
  );
  it.effect(
    "synchronizes more than 100 items and summaries across mutable pages, removals and recreation",
    () =>
      Effect.gen(function* () {
        const f = yield* setup;
        for (let i = 0; i < 105; i++) {
          yield* f.thread(`thread-${i}`);
          yield* f.activity(`thread-${i}`, "approval.requested", "request");
        }
        const stream = yield* f.connect({ pageSize: 17 });
        let cache = emptyAttentionSync();
        const frames: AttentionStreamMessage[] = [];
        const read = Effect.gen(function* () {
          const frame = yield* stream.next();
          frames.push(frame);
          cache = reduceAttentionStream(cache, frame);
          assert.notEqual(cache.status, "reset-required");
          assert.lengthOf(cache.notificationCandidates, 0);
          return frame;
        });
        assert.equal((yield* read).type, "begin");
        assert.equal((yield* read).type, "page");
        yield* f.activity("thread-0", "approval.resolved", "request");
        yield* f.engine.dispatch({
          type: "thread.delete",
          commandId: f.command(),
          threadId: ThreadId.make("thread-1"),
        });
        yield* f.thread("thread-1");
        yield* f.activity("thread-1", "user-input.requested", "new");
        yield* f.thread("000-insert-before-keyset");
        yield* f.activity("000-insert-before-keyset", "approval.requested", "new");
        let beforeFence = false;
        while (true) {
          const frame = yield* read;
          if (frame.type === "sync-complete") break;
          if (frame.type === "page" && frame.entries.length < 17 && !beforeFence) {
            beforeFence = true;
            yield* f.activity("thread-3", "user-input.requested", "between-page-and-fence");
          }
          assert.equal(HashMap.size(cache.entries), 0);
          assert.isBelow(frames.length, 100);
        }
        assert.isTrue(beforeFence);
        const expected = yield* f.sql<{
          readonly entity_key: string;
          readonly data_json: string;
          readonly version: number;
        }>`
        SELECT entity_key, data_json, version FROM attention_delivery_rows WHERE status != 'resolved' ORDER BY entity_key
      `;
        const decoded = yield* Effect.forEach(expected, (row) =>
          decodeEntity(row.data_json).pipe(
            Effect.map((entity) => ({
              key: row.entity_key,
              version: row.version,
              entity,
            })),
          ),
        );
        assert.deepEqual(
          [...HashMap.values(cache.entries)].sort((a, b) => a.key.localeCompare(b.key)),
          decoded,
        );
        assert.isAbove(HashMap.size(cache.entries), 200);
        yield* f.activity("thread-2", "approval.resolved", "request");
        const live = yield* stream.next();
        assert.equal(live.type, "delta");
        cache = reduceAttentionStream(cache, live);
        assert.equal(cache.status, "live");
        assert.isAbove(cache.notificationCandidates.length, 0);
      }).pipe(Effect.scoped, Effect.provide(Layer.fresh(layer()))),
  );

  it.effect(
    "resumes only a complete replay interval and rejects altered scope or malformed cursors",
    () =>
      Effect.gen(function* () {
        const f = yield* setup;
        yield* f.thread("thread");
        const stream = yield* f.connect();
        let cache = emptyAttentionSync();
        while (cache.status !== "live") cache = reduceAttentionStream(cache, yield* stream.next());
        const cursor = cache.cursor!;
        yield* f.activity("thread", "approval.requested", "request");
        const resumed = yield* f.connect({ cursor });
        cache = attentionSyncFailed(cache, "disconnected");
        while (cache.status !== "live") {
          cache = reduceAttentionStream(cache, yield* resumed.next());
          assert.lengthOf(cache.notificationCandidates, 0);
        }
        assert.equal(HashMap.size(cache.entries), 2);
        const changed = yield* f.connect({ cursor, filter: { includeResolved: true } });
        const failure = yield* changed.next().pipe(Effect.result);
        assert.equal(failure._tag, "Failure");
        const badScope = yield* Stream.runHead(
          makeAttentionStream(
            { cursor },
            { ...f.options, environmentId: EnvironmentId.make("other") },
          ),
        ).pipe(Effect.result);
        assert.equal(badScope._tag, "Failure");
        const malformed = yield* f.connect({
          cursor: AttentionDeliveryCursor.make("invalid.token"),
        });
        assert.equal((yield* malformed.next().pipe(Effect.result))._tag, "Failure");
        yield* f.sql`DELETE FROM attention_delivery_changes`;
        yield* f.sql`UPDATE attention_delivery_state SET floor = head`;
        const expired = yield* f.connect({ cursor });
        assert.deepEqual(yield* expired.next(), {
          type: "reset-required",
          reason: "replay-unavailable",
        });
      }).pipe(Effect.scoped, Effect.provide(Layer.fresh(layer()))),
  );

  it.effect("resets on rebuild and bootstrap expiry instead of claiming an incomplete fence", () =>
    Effect.gen(function* () {
      const f = yield* setup;
      yield* f.thread("thread");
      const stream = yield* f.connect({ pageSize: 1 });
      yield* stream.next();
      yield* f.attention.reset;
      yield* f.pipeline.bootstrap;
      assert.deepEqual(yield* stream.next(), {
        type: "reset-required",
        reason: "generation-changed",
      });
      const expired = yield* f.connect();
      yield* expired.next();
      yield* TestClock.adjust(ATTENTION_BOOTSTRAP_MS + 1);
      assert.deepEqual(yield* expired.next(), {
        type: "reset-required",
        reason: "bootstrap-expired",
      });
    }).pipe(Effect.scoped, Effect.provide(Layer.fresh(layer()))),
  );

  it.effect("emits empty filtered deltas and surfaces revoked authority while idle", () =>
    Effect.gen(function* () {
      const f = yield* setup;
      yield* f.thread("thread");
      const stream = yield* f.connect({
        filter: { threadIds: [ThreadId.make("not-this-thread")] },
      });
      let cache = emptyAttentionSync();
      while (cache.status !== "live") cache = reduceAttentionStream(cache, yield* stream.next());
      assert.equal(HashMap.size(cache.entries), 0);
      yield* f.activity("thread", "approval.requested", "request");
      const change = yield* stream.next();
      assert.equal(change.type, "delta");
      if (change.type === "delta") assert.deepEqual(change.changes, []);
      const waiting = yield* stream.next().pipe(Effect.forkScoped);
      yield* f.revoke;
      assert.equal((yield* Fiber.join(waiting).pipe(Effect.result))._tag, "Failure");
      assert.equal(attentionSyncFailed(cache, "unauthorized").status, "reset-required");
    }).pipe(Effect.scoped, Effect.provide(Layer.fresh(layer()))),
  );

  it.effect(
    "registers before a committed watermark and never reads an in-flight rolled-back projection",
    () =>
      Effect.gen(function* () {
        const f = yield* setup;
        yield* f.thread("thread");
        const registered = yield* Deferred.make<void>();
        const proceed = yield* Deferred.make<void>();
        const pull = yield* Stream.toPull(
          makeAttentionStream({}, f.options).pipe(
            Stream.provideService(OrchestrationEngineService, {
              ...f.engine,
              subscribeDomainEvents: f.engine.subscribeDomainEvents.pipe(
                Effect.tap(() =>
                  Deferred.succeed(registered, undefined).pipe(
                    Effect.andThen(Deferred.await(proceed)),
                  ),
                ),
              ),
            }),
          ),
        );
        const first = yield* pull.pipe(Effect.forkScoped);
        yield* Deferred.await(registered);
        yield* f.activity("thread", "approval.requested", "during-registration");
        yield* Deferred.succeed(proceed, undefined);
        let cache = reduceAttentionStream(emptyAttentionSync(), (yield* Fiber.join(first))[0]!);
        const written = yield* Deferred.make<void>();
        const rollback = yield* Deferred.make<void>();
        const transaction = yield* f.sql
          .withTransaction(
            Effect.gen(function* () {
              yield* f.sql`UPDATE projection_thread_attention_current SET reason_code = 'response_failed', revision = revision + 1`;
              yield* Deferred.succeed(written, undefined);
              yield* Deferred.await(rollback);
              return yield* Effect.fail("intentional-rollback");
            }),
          )
          .pipe(Effect.result, Effect.forkScoped);
        yield* Deferred.await(written);
        const page = yield* pull.pipe(Effect.forkScoped);
        yield* Deferred.succeed(rollback, undefined);
        assert.equal((yield* Fiber.join(transaction))._tag, "Failure");
        cache = reduceAttentionStream(cache, (yield* Fiber.join(page))[0]!);
        while (cache.status !== "live") cache = reduceAttentionStream(cache, (yield* pull)[0]!);
        assert.equal(HashMap.size(cache.entries), 2);
        const item = [...HashMap.values(cache.entries)].find(
          (entry) => entry.entity?.type === "item",
        );
        assert.equal(
          item?.entity?.type === "item" ? item.entity.value.reasonCode : null,
          "approval_requested",
        );
      }).pipe(Effect.scoped, Effect.provide(Layer.fresh(layer()))),
  );

  it.effect("resets a slow consumer on retention overflow and rejects oversized UTF-8 rows", () =>
    Effect.gen(function* () {
      const f = yield* setup;
      yield* f.thread("thread");
      const slow = yield* f.connect({ pageSize: 1 });
      yield* slow.next();
      yield* f.sql`
        WITH RECURSIVE changes(n) AS (SELECT 1 UNION ALL SELECT n+1 FROM changes WHERE n < 1100)
        INSERT INTO attention_delivery_changes (entity_key,bytes,oversized)
        SELECT 'summary:retention-fixture', 9000, 0 FROM changes
      `;
      const usage = yield* f.sql<{ readonly n: number; readonly bytes: number }>`
        SELECT COUNT(*) AS n, SUM(bytes) AS bytes FROM attention_delivery_changes
      `;
      assert.isAtMost(usage[0]!.n, 1000);
      assert.isAtMost(usage[0]!.bytes, 8 * 1024 * 1024);
      assert.deepEqual(yield* slow.next(), {
        type: "reset-required",
        reason: "replay-unavailable",
      });
      yield* f.activity("thread", "approval.requested", "é".repeat(40000));
      const oversized = yield* f.connect();
      yield* oversized.next();
      assert.deepEqual(yield* oversized.next(), {
        type: "reset-required",
        reason: "message-too-large",
      });
    }).pipe(Effect.scoped, Effect.provide(Layer.fresh(layer()))),
  );

  it.effect(
    "enforces page-token separation, detects journal holes and waits for a new bootstrap during rebuild",
    () =>
      Effect.gen(function* () {
        const f = yield* setup;
        yield* f.thread("thread");
        const stream = yield* f.connect();
        const begin = yield* stream.next();
        assert.equal(begin.type, "begin");
        const page = yield* stream.next();
        assert.equal(page.type, "page");
        if (page.type === "page") {
          const wrongToken = yield* f.connect({
            cursor: AttentionDeliveryCursor.make(page.pageToken),
          });
          assert.equal((yield* wrongToken.next().pipe(Effect.result))._tag, "Failure");
        }
        while ((yield* stream.next()).type !== "sync-complete") {}
        yield* f.activity("thread", "approval.requested", "one");
        yield* f.sql`DELETE FROM attention_delivery_changes WHERE sequence =
        (SELECT MIN(sequence) FROM attention_delivery_changes WHERE sequence > 1)`;
        assert.deepEqual(yield* stream.next(), {
          type: "reset-required",
          reason: "replay-unavailable",
        });
        yield* f.attention.reset;
        const rebuilding = yield* f.connect();
        assert.deepEqual(yield* rebuilding.next(), {
          type: "reset-required",
          reason: "rebuilding",
        });
      }).pipe(Effect.scoped, Effect.provide(Layer.fresh(layer()))),
  );
});

// @effect-diagnostics nodeBuiltinImport:off
import * as NodeCrypto from "node:crypto";
import {
  AttentionDeliveryCursor,
  AttentionPageToken,
  AttentionEntity,
  AttentionStreamMessage,
  AttentionSyncError,
  type AttentionSubscribeInput,
  type AttentionFilter,
  type AttentionChange,
  type AttentionResetReason,
  type EnvironmentId,
  type EnvironmentAuthorizationError,
  NonNegativeInt,
} from "@t3tools/contracts";
import * as Effect from "effect/Effect";
import * as Clock from "effect/Clock";
import * as Schema from "effect/Schema";
import * as Queue from "effect/Queue";
import * as Stream from "effect/Stream";
import * as Option from "effect/Option";
import * as Scope from "effect/Scope";
import * as Exit from "effect/Exit";
import * as SqlClient from "effect/unstable/sql/SqlClient";
import { OrchestrationEngineService } from "./Services/OrchestrationEngine.ts";
import { ProjectionThreadAttentionCurrentRepository } from "../persistence/Services/ProjectionThreadAttentionCurrent.ts";
import { makeLiveStreamBudget } from "./LiveStreamBudget.ts";
import { affectsCurrentAttention } from "../persistence/Layers/ProjectionThreadAttentionCurrent.ts";

export const ATTENTION_MESSAGE_BYTES = 64 * 1024;
export const ATTENTION_BOOTSTRAP_MS = 30_000;
const tokenSchema = Schema.Struct({
  kind: Schema.Literals(["cursor", "page"]),
  generation: Schema.String,
  binding: Schema.String,
  position: NonNegativeInt,
  expiresAt: NonNegativeInt,
});
const encodeToken = Schema.encodeSync(Schema.fromJsonString(tokenSchema));
const decodeToken = Schema.decodeUnknownOption(Schema.fromJsonString(tokenSchema));
const decodeEntity = Schema.decodeUnknownEffect(Schema.fromJsonString(AttentionEntity));
const encodeFrame = Schema.encodeSync(Schema.fromJsonString(AttentionStreamMessage));
const encodeFilter = Schema.encodeSync(
  Schema.fromJsonString(
    Schema.Struct({
      environmentId: Schema.String,
      scope: Schema.String,
      projects: Schema.Array(Schema.String),
      threads: Schema.Array(Schema.String),
      resolved: Schema.Boolean,
    }),
  ),
);

export function attentionFilterBinding(
  environmentId: EnvironmentId,
  scope: string,
  filter: AttentionFilter,
) {
  return NodeCrypto.createHash("sha256")
    .update(
      encodeFilter({
        environmentId,
        scope,
        projects: [...new Set(filter.projectIds)].sort(),
        threads: [...new Set(filter.threadIds)].sort(),
        resolved: filter.includeResolved === true,
      }),
    )
    .digest("hex");
}
interface DeliveryState {
  readonly generation: string;
  readonly head: number;
  readonly floor: number;
  readonly ready: number;
}
interface StoredRow {
  readonly entity_key: string;
  readonly version: number;
  readonly data_json: string | null;
  readonly oversized: number;
  readonly project_id: string | null;
  readonly thread_id: string | null;
  readonly status: string | null;
  readonly before_project?: string | null;
  readonly before_thread?: string | null;
  readonly before_status?: string | null;
}

/** One subscription owns bootstrap, replay and live mode. Domain events are only post-commit wakeups. */
export const makeAttentionStream = (
  input: AttentionSubscribeInput,
  options: {
    readonly environmentId: EnvironmentId;
    readonly scopeBinding: string;
    readonly secret: Uint8Array;
    readonly authorize: Effect.Effect<void, EnvironmentAuthorizationError | AttentionSyncError>;
    readonly authorizationChanges: Stream.Stream<unknown>;
    readonly expiresAtMs?: number;
  },
) =>
  Stream.unwrap(
    Effect.gen(function* () {
      const sql = yield* SqlClient.SqlClient;
      const engine = yield* OrchestrationEngineService;
      const attention = yield* ProjectionThreadAttentionCurrentRepository;
      const filter = input.filter ?? {};
      const pageSize = input.pageSize ?? 50;
      const binding = attentionFilterBinding(options.environmentId, options.scopeBinding, filter);
      const sign = (payload: typeof tokenSchema.Type) => {
        const body = Buffer.from(encodeToken(payload)).toString("base64url");
        return `${body}.${NodeCrypto.createHmac("sha256", options.secret).update(body).digest("base64url")}`;
      };
      const parse = (cursor: AttentionDeliveryCursor) => {
        const parts = cursor.split(".");
        if (parts.length !== 2) return Option.none<typeof tokenSchema.Type>();
        const body = parts[0]!,
          signature = Buffer.from(parts[1]!, "base64url");
        const expected = NodeCrypto.createHmac("sha256", options.secret).update(body).digest();
        if (
          signature.length !== expected.length ||
          !NodeCrypto.timingSafeEqual(signature, expected)
        )
          return Option.none<typeof tokenSchema.Type>();
        return decodeToken(Buffer.from(body, "base64url").toString("utf8"));
      };
      const wake = yield* Queue.sliding<void>(1);
      yield* Effect.addFinalizer(() => Queue.shutdown(wake));
      const watches = yield* Scope.fork(yield* Effect.scope);
      const domain = yield* engine.subscribeDomainEvents.pipe(Scope.provide(watches));
      const resets = yield* attention.subscribeResets.pipe(Scope.provide(watches));
      yield* Stream.mergeAll(
        [
          domain.pipe(
            Stream.filter(affectsCurrentAttention),
            Stream.map(() => undefined),
          ),
          resets,
          options.authorizationChanges.pipe(Stream.map(() => undefined)),
        ],
        { concurrency: "unbounded" },
      ).pipe(
        Stream.runForEach(() => Queue.offer(wake, undefined)),
        Effect.forkIn(watches),
      );
      const state = () =>
        sql<DeliveryState>`SELECT generation, head, floor, ready FROM attention_delivery_state WHERE id=1`.pipe(
          Effect.flatMap((rows) =>
            rows[0]
              ? Effect.succeed(rows[0])
              : Effect.fail(
                  new AttentionSyncError({
                    reason: "unavailable",
                    message: "Attention delivery state is unavailable.",
                  }),
                ),
          ),
        );
      // NodeSqliteClient serializes this short transaction with the projection writer.
      yield* options.authorize;
      const initial = yield* sql
        .withTransaction(options.authorize.pipe(Effect.andThen(state())))
        .pipe(
          Effect.catchTag("SqlError", () =>
            Effect.fail(
              new AttentionSyncError({
                reason: "unavailable",
                message: "Could not capture attention watermark.",
              }),
            ),
          ),
        );
      const started = yield* Clock.currentTimeMillis;
      let position = initial.head;
      const generation = initial.generation;
      let pendingReset: AttentionResetReason | undefined = initial.ready ? undefined : "rebuilding";
      if (input.cursor !== undefined) {
        const token = parse(input.cursor);
        if (Option.isNone(token) || token.value.kind !== "cursor")
          return yield* new AttentionSyncError({
            reason: "invalid-cursor",
            message: "Malformed attention delivery cursor.",
          });
        if (token.value.binding !== binding)
          return yield* new AttentionSyncError({
            reason: "cursor-scope-mismatch",
            message:
              "Attention cursor belongs to another environment, filter or authorized session.",
          });
        if (token.value.generation !== generation) pendingReset = "generation-changed";
        else if (
          token.value.expiresAt < started ||
          token.value.position < initial.floor ||
          token.value.position > initial.head
        )
          pendingReset = "replay-unavailable";
        else position = token.value.position;
      }
      const cursorAt = (value: number) =>
        AttentionDeliveryCursor.make(
          sign({
            kind: "cursor",
            generation,
            binding,
            position: value,
            expiresAt: started + 24 * 60 * 60 * 1000,
          }),
        );
      let cursor = input.cursor && !pendingReset ? input.cursor : cursorAt(position);
      let phase: "begin" | "pages" | "fence" | "replay" | "live" | "ended" = "begin";
      let afterKey = "";
      let pageIndex = 0;
      let previousPageToken: AttentionPageToken | null = null;
      let fence = initial.head;
      yield* Effect.sleep(ATTENTION_BOOTSTRAP_MS).pipe(
        Effect.andThen(
          Effect.suspend(() =>
            phase === "live" || phase === "ended"
              ? Effect.void
              : Effect.gen(function* () {
                  pendingReset = "bootstrap-expired";
                  yield* Scope.close(watches, Exit.void);
                  yield* Queue.offer(wake, undefined);
                }),
          ),
        ),
        Effect.forkScoped,
      );
      if (options.expiresAtMs !== undefined)
        yield* Effect.sleep(Math.max(0, options.expiresAtMs - started)).pipe(
          Effect.andThen(Queue.offer(wake, undefined)),
          Effect.forkScoped,
        );
      const matches = (
        project: string | null | undefined,
        thread: string | null | undefined,
        status: string | null | undefined,
      ) =>
        project != null &&
        thread != null &&
        (!filter.projectIds?.length || filter.projectIds.some((id) => id === project)) &&
        (!filter.threadIds?.length || filter.threadIds.some((id) => id === thread)) &&
        (filter.includeResolved === true || status !== "resolved");
      const reset = (reason: AttentionResetReason): AttentionStreamMessage => {
        phase = "ended";
        return { type: "reset-required", reason };
      };
      const checkpoint = () => ({
        environmentId: options.environmentId,
        generation,
        cursor,
        position,
      });
      const next = Effect.fn("AttentionSync.next")(function* (): Effect.fn.Return<
        AttentionStreamMessage | undefined,
        AttentionSyncError | EnvironmentAuthorizationError
      > {
        if (phase === "ended") return undefined;
        yield* options.authorize;
        if (pendingReset) return reset(pendingReset);
        while (true) {
          const now = yield* Clock.currentTimeMillis;
          if (phase !== "live" && now - started >= ATTENTION_BOOTSTRAP_MS)
            return reset("bootstrap-expired");
          const result = yield* sql
            .withTransaction(
              Effect.gen(function* () {
                yield* options.authorize;
                const current = yield* state();
                if (current.generation !== generation)
                  return { reset: "generation-changed" as const };
                if (!current.ready) return { reset: "rebuilding" as const };
                if (position < current.floor || position > current.head)
                  return { reset: "replay-unavailable" as const };
                if (phase === "begin") return { current };
                if (phase === "pages") {
                  const rows = yield* sql<StoredRow>`
            SELECT CASE WHEN bytes > ${ATTENTION_MESSAGE_BYTES} THEN '' ELSE entity_key END AS entity_key,
              version, CASE WHEN bytes > ${ATTENTION_MESSAGE_BYTES} THEN NULL ELSE data_json END AS data_json,
              CASE WHEN bytes > ${ATTENTION_MESSAGE_BYTES} THEN 1 ELSE 0 END AS oversized,
              CASE WHEN bytes > ${ATTENTION_MESSAGE_BYTES} THEN NULL ELSE project_id END AS project_id,
              CASE WHEN bytes > ${ATTENTION_MESSAGE_BYTES} THEN NULL ELSE thread_id END AS thread_id, status
            FROM attention_delivery_rows WHERE entity_key > ${afterKey}
              ${filter.projectIds?.length ? sql`AND ${sql.in("project_id", filter.projectIds)}` : sql``}
              ${filter.threadIds?.length ? sql`AND ${sql.in("thread_id", filter.threadIds)}` : sql``}
              ${filter.includeResolved ? sql`` : sql`AND status != 'resolved'`}
            ORDER BY entity_key LIMIT ${pageSize}
          `;
                  return { rows, current };
                }
                if (phase === "fence") return { current };
                const through = phase === "replay" ? fence : current.head;
                const rows = yield* sql<StoredRow>`
          SELECT CASE WHEN oversized THEN '' ELSE entity_key END AS entity_key,
            sequence AS version, data_json, oversized,
            CASE WHEN oversized THEN NULL ELSE project_id END AS project_id,
            CASE WHEN oversized THEN NULL ELSE thread_id END AS thread_id, status,
            CASE WHEN oversized THEN NULL ELSE before_project END AS before_project,
            CASE WHEN oversized THEN NULL ELSE before_thread END AS before_thread, before_status
          FROM attention_delivery_changes WHERE sequence > ${position} AND sequence <= ${through}
          ORDER BY sequence LIMIT ${pageSize}
        `;
                return { rows, current, through };
              }),
            )
            .pipe(
              Effect.catchTag("SqlError", () =>
                Effect.fail(
                  new AttentionSyncError({
                    reason: "unavailable",
                    message: "Could not read attention delivery state.",
                  }),
                ),
              ),
            );
          if ("reset" in result) return reset(result.reset);
          if (phase === "begin") {
            phase = input.cursor === undefined ? "pages" : "fence";
            return {
              ...checkpoint(),
              type: "begin",
              mode: input.cursor === undefined ? "snapshot" : "resume",
            };
          }
          if (phase === "fence") {
            fence = result.current.head;
            phase = "replay";
            continue;
          }
          if (!("rows" in result))
            return yield* new AttentionSyncError({
              reason: "unavailable",
              message: "Invalid attention stream phase.",
            });
          const changes: AttentionChange[] = [];
          let bytes = 4096;
          const beforeCursor = cursor;
          let consumed = 0;
          for (const row of result.rows) {
            if (phase !== "pages" && row.version !== position + 1)
              return reset("replay-unavailable");
            if (row.oversized) return reset("message-too-large");
            const entity =
              row.data_json === null
                ? null
                : yield* decodeEntity(row.data_json).pipe(
                    Effect.mapError(
                      () =>
                        new AttentionSyncError({
                          reason: "unavailable",
                          message: "Invalid projected attention record.",
                        }),
                    ),
                  );
            const include = matches(row.project_id, row.thread_id, row.status);
            const exited = matches(row.before_project, row.before_thread, row.before_status);
            const change = {
              key: row.entity_key,
              version: row.version,
              entity: include ? entity : null,
            };
            const size =
              Buffer.byteLength(row.data_json ?? "") + Buffer.byteLength(row.entity_key) + 256;
            if (bytes + size > ATTENTION_MESSAGE_BYTES && consumed > 0) break;
            if (bytes + size > ATTENTION_MESSAGE_BYTES) return reset("message-too-large");
            bytes += size;
            if (phase === "pages" || include || exited) changes.push(change);
            consumed++;
            if (phase === "pages") afterKey = row.entity_key;
            else position = row.version;
          }
          if (phase === "pages") {
            const pageToken = AttentionPageToken.make(
              sign({
                kind: "page",
                generation,
                binding,
                position: ++pageIndex,
                expiresAt: started + ATTENTION_BOOTSTRAP_MS,
              }),
            );
            const message: AttentionStreamMessage = {
              ...checkpoint(),
              type: "page",
              pageToken,
              previousPageToken,
              entries: changes,
            };
            previousPageToken = pageToken;
            if (consumed === result.rows.length && result.rows.length < pageSize) phase = "fence";
            return message;
          }
          if (consumed > 0) {
            cursor = cursorAt(position);
            return {
              ...checkpoint(),
              type: "delta",
              after: beforeCursor,
              notificationEligible: phase === "live",
              changes,
            };
          }
          if ("through" in result && position < result.through) return reset("replay-unavailable");
          if (phase === "replay") {
            if (position !== fence) return reset("replay-unavailable");
            position = fence;
            cursor = cursorAt(position);
            phase = "live";
            return { ...checkpoint(), type: "sync-complete" };
          }
          yield* Queue.take(wake).pipe(Effect.orDie);
          yield* options.authorize;
        }
      });
      const budget = yield* makeLiveStreamBudget();
      const frames = Stream.unfold(undefined, () =>
        next().pipe(
          Effect.flatMap((message) => {
            if (message === undefined) return Effect.succeed(undefined);
            const bounded =
              Buffer.byteLength(encodeFrame(message)) <= ATTENTION_MESSAGE_BYTES
                ? message
                : reset("message-too-large");
            return budget.retain(bounded).pipe(Effect.map((value) => [value, undefined] as const));
          }),
        ),
      );
      return budget
        .deliver(frames)
        .pipe(
          Stream.catchTag("OrchestrationGetSnapshotError", () =>
            Stream.make(reset("backpressure")),
          ),
        );
    }),
  );

