        commandId: CommandId.make("cmd-retry-plan-1"),
        threadId,
        proposedPlan: {
          id: "plan-retry-1",
          turnId: null,
          planMarkdown: "# Plan",
          implementedAt: null,
          implementationThreadId: null,
          createdAt,
          updatedAt: createdAt,
        },
        createdAt,
