                    createdAt,
                  },
                  runSetupScript: false,
                },
                createdAt,
              }),
            );
            yield* Fiber.join(bootstrapCreate);
          }),
        ),
      );
      assert.deepEqual(trace, [
        "thread.create",
        "drain:1",
        "thread.message.user.append",
